begin;
insert into auth.sessions(id,user_id) select md5('pgtap-session:'||id::text)::uuid,id from auth.users;
set local search_path=extensions,public,private;
select no_plan();
update private.meetup_feature_config set enabled=true,expanded_launch_gates_passed=true where id=1;
select ok(not has_function_privilege('anon','public.list_meetup_room_members(uuid)','EXECUTE'),'anonymous callers cannot enumerate event rooms');
select ok(not has_function_privilege('service_role','public.send_meetup_room_media_once(uuid,uuid,uuid,text)','EXECUTE'),'workers cannot impersonate media senders');
select ok(not (select public from storage.buckets where id='meetup-room-media'),'event room media bucket is private');
set local role authenticated;
select set_config('request.jwt.claim.role','authenticated',true);
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000001',true);
select set_config('request.jwt.claims',jsonb_build_object('sub','10000000-0000-0000-0000-000000000001','session_id',md5('pgtap-session:10000000-0000-0000-0000-000000000001')::uuid)::text,true);
select set_config('test.event',public.create_meetup_draft(jsonb_build_object(
 'title','Event media fixture','description','Synthetic adult members and moderated room attachments.',
 'category','community','tags',jsonb_build_array('community'),'startsAt',now()+interval '48 hours',
 'accessMode','open','locationVisibility','protected','generalAreaId','reykjavik',
 'latitude',64.1482,'longitude',-21.9511,'prohibitedServicesAttested',true))::text,true);
select public.publish_meetup(current_setting('test.event')::uuid);
select set_config('test.room',public.get_meetup_room_summary(current_setting('test.event')::uuid)->>'id',true);
select is(jsonb_array_length(public.list_meetup_room_members(current_setting('test.room')::uuid)),1,'host is initially the only room member');
select is(public.list_meetup_room_members(current_setting('test.room')::uuid)#>>'{0,role}','host','roster identifies the owner');
select ok((public.get_meetup_room_summary(current_setting('test.event')::uuid)->>'canManageAvatar')::boolean,'host can edit open room avatar');
select set_config('test.avatar_a',public.reserve_media_upload('meetup_room_avatar',current_setting('test.room')::uuid,'image')::text,true);
select set_config('test.avatar_b',public.reserve_media_upload('meetup_room_avatar',current_setting('test.room')::uuid,'image')::text,true);
select is(public.get_meetup_room_summary(current_setting('test.event')::uuid)->>'avatarPath',null::text,'pending avatar is never published');
select throws_ok($$select public.reserve_media_upload('meetup_room_avatar',current_setting('test.room')::uuid,'video')$$,'22023','invalid_media_type','group avatar is image-only');
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000002',true);
select set_config('request.jwt.claims',jsonb_build_object('sub','10000000-0000-0000-0000-000000000002','session_id',md5('pgtap-session:10000000-0000-0000-0000-000000000002')::uuid)::text,true);
select throws_ok($$select public.list_meetup_room_members(current_setting('test.room')::uuid)$$,'42501','active_room_membership_required','unrelated profile cannot read roster');
select public.join_meetup(current_setting('test.event')::uuid);
select is(jsonb_array_length(public.list_meetup_room_members(current_setting('test.room')::uuid)),2,'admitted participant sees host and admitted members');
select ok(not (public.get_meetup_room_summary(current_setting('test.event')::uuid)->>'canManageAvatar')::boolean,'participant has no avatar controls');
select throws_ok($$select public.remove_meetup_room_avatar(current_setting('test.room')::uuid)$$,'42501','owned_room_required','participant cannot remove group photo');
select throws_ok($$select public.reserve_media_upload('meetup_room_avatar',current_setting('test.room')::uuid,'image')$$,'42501','media_target_unavailable','participant cannot upload group photo');
select set_config('test.photo',public.reserve_media_upload('meetup_room_message',current_setting('test.room')::uuid,'image','{"clientMessageId":"a3100000-0000-4000-8000-000000000001","tags":[]}')::text,true);
select is(public.reserve_media_upload('meetup_room_message',current_setting('test.room')::uuid,'image','{"clientMessageId":"a3100000-0000-4000-8000-000000000001"}')->>'id',current_setting('test.photo')::jsonb->>'id','same client message reuses reservation');
select throws_ok($$select public.reserve_media_upload('meetup_room_message',current_setting('test.room')::uuid,'video','{"clientMessageId":"a3100000-0000-4000-8000-000000000001"}')$$,'23505','message_id_conflict','client ID cannot change media type');
select is(public.send_meetup_room_media_once(current_setting('test.room')::uuid,'a3100000-0000-4000-8000-000000000001',(current_setting('test.photo')::jsonb->>'id')::uuid)#>>'{media,status}','pending','captionless photo has durable pending receipt');
select ok(not (public.send_meetup_room_media_once(current_setting('test.room')::uuid,'a3100000-0000-4000-8000-000000000001',(current_setting('test.photo')::jsonb->>'id')::uuid)->'media' ? 'storagePath'),'pending photo never exposes unreviewed paths');
select throws_ok($$select public.send_meetup_room_media_once(current_setting('test.room')::uuid,'a3100000-0000-4000-8000-000000000001',(current_setting('test.photo')::jsonb->>'id')::uuid,'Changed caption')$$,'23505','message_id_conflict','retry cannot change caption');
select throws_ok($$select public.send_meetup_room_message_once(current_setting('test.room')::uuid,'a3100000-0000-4000-8000-000000000001','')$$,'23505','message_id_conflict','text send cannot reuse photo message ID');
select set_config('test.cancelled',public.reserve_media_upload('meetup_room_message',current_setting('test.room')::uuid,'image','{"clientMessageId":"a3100000-0000-4000-8000-000000000003"}')::text,true);
select public.cancel_media_upload((current_setting('test.cancelled')::jsonb->>'id')::uuid);
select isnt(public.reserve_media_upload('meetup_room_message',current_setting('test.room')::uuid,'image','{"clientMessageId":"a3100000-0000-4000-8000-000000000003"}')->>'id',current_setting('test.cancelled')::jsonb->>'id','cancelled failed upload retry gets fresh reservation');
select set_config('test.video',public.reserve_media_upload('meetup_room_message',current_setting('test.room')::uuid,'video','{"clientMessageId":"a3100000-0000-4000-8000-000000000002"}')::text,true);
select throws_ok($$insert into storage.objects(bucket_id,name) values('meetup-room-media',current_setting('test.room')||'/raw.jpg')$$,'42501',null::text,'members cannot bypass media inspection');
reset role;
select is((select status from private.media_uploads where id=(current_setting('test.avatar_a')::jsonb->>'id')::uuid),'rejected','new avatar request cancels previous candidate');
update private.media_uploads set status='processing',claim_id='a3200000-0000-4000-8000-000000000001',expires_at=now()+interval '15 minutes'
 where id in ((current_setting('test.avatar_b')::jsonb->>'id')::uuid,(current_setting('test.photo')::jsonb->>'id')::uuid,(current_setting('test.video')::jsonb->>'id')::uuid);
set local role service_role;
select set_config('request.jwt.claim.role','service_role',true);
select set_config('request.jwt.claim.sub','',true);
select set_config('request.jwt.claims','{}',true);
select ok(not public.finish_media_upload((current_setting('test.avatar_a')::jsonb->>'id')::uuid,'a3200000-0000-4000-8000-000000000001',100,null,current_setting('test.room')||'/'||(current_setting('test.avatar_a')::jsonb->>'id')||'.jpg',null,null),'obsolete avatar cannot overwrite latest request');
select ok(public.finish_media_upload((current_setting('test.avatar_b')::jsonb->>'id')::uuid,'a3200000-0000-4000-8000-000000000001',100,null,current_setting('test.room')||'/'||(current_setting('test.avatar_b')::jsonb->>'id')||'.jpg',null,null),'reviewed current avatar publishes');
select ok(public.finish_media_upload((current_setting('test.photo')::jsonb->>'id')::uuid,'a3200000-0000-4000-8000-000000000001',100,null,current_setting('test.room')||'/'||(current_setting('test.photo')::jsonb->>'id')||'.jpg',null,null),'reviewed image publishes');
select throws_ok($$select public.finish_media_upload((current_setting('test.video')::jsonb->>'id')::uuid,'a3200000-0000-4000-8000-000000000001',100,1000,current_setting('test.room')||'/'||(current_setting('test.video')::jsonb->>'id')||'.mp4',null,null)$$,'22023','invalid_verified_media','video requires verified poster');
select ok(public.finish_media_upload((current_setting('test.video')::jsonb->>'id')::uuid,'a3200000-0000-4000-8000-000000000001',100,1000,current_setting('test.room')||'/'||(current_setting('test.video')::jsonb->>'id')||'.mp4',current_setting('test.room')||'/'||(current_setting('test.video')::jsonb->>'id')||'-thumb.jpg',null),'worker may complete before send receipt');
set local role authenticated;
select set_config('request.jwt.claim.role','authenticated',true);
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000002',true);
select set_config('request.jwt.claims',jsonb_build_object('sub','10000000-0000-0000-0000-000000000002','session_id',md5('pgtap-session:10000000-0000-0000-0000-000000000002')::uuid)::text,true);
select is(public.send_meetup_room_media_once(current_setting('test.room')::uuid,'a3100000-0000-4000-8000-000000000002',(current_setting('test.video')::jsonb->>'id')::uuid)#>>'{media,status}','approved','late send attaches already-approved worker result');
select ok((public.reserve_media_upload('meetup_room_message',current_setting('test.room')::uuid,'video','{"clientMessageId":"a3100000-0000-4000-8000-000000000002"}')->>'alreadyUploaded')::boolean,'approved upload retry skips recreating quarantine');
select is((select item->>'lastMessageKind' from jsonb_array_elements(public.list_meetup_chats())item where item->>'id'=current_setting('test.room')),'video','inbox identifies captionless media');
select is(public.get_meetup_room_summary(current_setting('test.event')::uuid)->>'avatarPath',current_setting('test.room')||'/'||(current_setting('test.avatar_b')::jsonb->>'id')||'.jpg','room summary returns approved avatar');
select ok(private.can_read_meetup_room_media(current_setting('test.room')||'/'||(current_setting('test.photo')::jsonb->>'id')||'.jpg'),'admitted participant can sign approved attachment');
select throws_ok($$select public.send_meetup_room_media_once(current_setting('test.room')::uuid,'a3100000-0000-4000-8000-000000000004',(current_setting('test.avatar_b')::jsonb->>'id')::uuid)$$,'42501','media_upload_unavailable','group avatar reservation cannot become a message attachment');
select set_config('test.review',public.reserve_media_upload('meetup_room_message',current_setting('test.room')::uuid,'image','{"clientMessageId":"a3100000-0000-4000-8000-000000000005"}')::text,true);
select public.send_meetup_room_media_once(current_setting('test.room')::uuid,'a3100000-0000-4000-8000-000000000005',(current_setting('test.review')::jsonb->>'id')::uuid);
reset role;
update private.media_uploads set status='processing',claim_id='a3200000-0000-4000-8000-000000000001',expires_at=now()+interval '15 minutes' where id=(current_setting('test.review')::jsonb->>'id')::uuid;
set local role service_role;
select set_config('request.jwt.claim.role','service_role',true);
select ok(public.finish_media_upload((current_setting('test.review')::jsonb->>'id')::uuid,'a3200000-0000-4000-8000-000000000001',null,null,null,null,'moderation_review_required'),'moderation review stores rejected state');
reset role;
select is((select count(*) from private.media_cleanup_jobs where bucket='meetup-room-media' and name=current_setting('test.room')||'/'||(current_setting('test.review')::jsonb->>'id')||'.jpg'),0::bigint,'reviewable rejection never schedules deletion of future approved output');
update private.media_uploads set status='processing',claim_id='a3200000-0000-4000-8000-000000000001',expires_at=now()+interval '15 minutes' where id=(current_setting('test.review')::jsonb->>'id')::uuid;
set local role service_role;
select ok(public.finish_media_upload((current_setting('test.review')::jsonb->>'id')::uuid,'a3200000-0000-4000-8000-000000000001',100,null,current_setting('test.room')||'/'||(current_setting('test.review')::jsonb->>'id')||'.jpg',null,null),'reviewed appeal publishes without stale deletion task');
reset role;
select is((select count(*) from private.media_cleanup_jobs where bucket='meetup-room-media' and name=current_setting('test.room')||'/'||(current_setting('test.review')::jsonb->>'id')||'.jpg'),0::bigint,'appeal approval does not inherit normalized cleanup');
set local role authenticated;
select set_config('request.jwt.claim.role','authenticated',true);
reset role;
update public.meetup_room_messages set hidden_at=now() where id='a3100000-0000-4000-8000-000000000001';
set local role authenticated;
select ok(not private.can_read_meetup_room_media(current_setting('test.room')||'/'||(current_setting('test.photo')::jsonb->>'id')||'.jpg'),'moderation immediately removes media signing access');
select public.leave_meetup(current_setting('test.event')::uuid);
select throws_ok($$select public.list_meetup_room_members(current_setting('test.room')::uuid)$$,'42501','active_room_membership_required','leaving removes roster access');
select ok(not private.can_read_meetup_room_media(current_setting('test.room')||'/'||(current_setting('test.video')::jsonb->>'id')||'.mp4'),'leaving removes video signing access');
reset role;
update public.meetup_rooms set posting_closes_at=now()-interval '1 minute',reading_closes_at=now()-interval '1 second' where id=current_setting('test.room')::uuid;
set local role authenticated;
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000001',true);
select set_config('request.jwt.claims',jsonb_build_object('sub','10000000-0000-0000-0000-000000000001','session_id',md5('pgtap-session:10000000-0000-0000-0000-000000000001')::uuid)::text,true);
select throws_ok($$select public.list_meetup_room_members(current_setting('test.room')::uuid)$$,'42501','active_room_membership_required','reading deadline removes host roster access');
select ok(not private.can_read_meetup_room_media(current_setting('test.room')||'/'||(current_setting('test.avatar_b')::jsonb->>'id')||'.jpg'),'reading deadline removes avatar signing access');
select * from finish();
rollback;
